PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName ?riskScore
WHERE {
  ?ph a wm:PortfolioHealth ;
      wm:riskScore ?riskScore ;
      wm:healthOfInvestor ?inv .
  FILTER(xsd:decimal(?riskScore) > 100)
  ?inv a wm:Investor ;
       wm:investorName ?investorName .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?marketScenario ?marketScenarioLabel (AVG(?absChange) AS ?avgAbsChange)
WHERE {
  ?rebalance a wm:ScenarioRebalancing ;
             wm:hasMarketScenario ?marketScenario ;
             wm:newAllocationPct ?newPct ;
             wm:currentAllocationPct ?currPct .

  BIND (ABS(xsd:decimal(?newPct) - xsd:decimal(?currPct)) AS ?absChange)

  OPTIONAL { ?marketScenario rdfs:label ?marketScenarioLabel . }
}
GROUP BY ?marketScenario ?marketScenarioLabel
ORDER BY DESC(?avgAbsChange)
LIMIT 5

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:hasPortfolioHealth ?ph .
  OPTIONAL { ?inv wm:investorName ?investorName . }
  ?ph wm:liquidityScore ?liq ;
      wm:diversificationScore ?div .
  FILTER ( xsd:decimal(?liq) < 25 && xsd:decimal(?div) < 25 )
}

PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolLabel ?goalCategory (COUNT(?investor) AS ?investorCount)
WHERE {
  {
    SELECT ?investor ?riskTol (COUNT(DISTINCT ?goal) AS ?goalCount)
    WHERE {
      ?investor a wm:Investor .
      ?investor wm:hasRiskTolerance ?riskTol .
      OPTIONAL { ?investor wm:hasInvestmentGoal ?goal . }
    }
    GROUP BY ?investor ?riskTol
    HAVING (COUNT(DISTINCT ?goal) >= 1)
  }
  BIND(
    IF(?goalCount = 1, "1",
      IF(?goalCount = 2, "2",
        IF(?goalCount = 3, "3", "4+")
      )
    ) AS ?goalCategory
  )
  OPTIONAL { ?riskTol rdfs:label ?riskTolLabel . }
}
GROUP BY ?riskTolLabel ?goalCategory
ORDER BY ?riskTolLabel ?goalCategory

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cat ?holdingCount ?investorCount WHERE {
  {
    SELECT ?cat (COUNT(?holding) AS ?holdingCount) WHERE {
      ?holding a wm:PortfolioHolding .
      ?holding wm:category ?cat .
    } GROUP BY ?cat
  }
  {
    SELECT ?cat (COUNT(DISTINCT ?inv) AS ?investorCount) WHERE {
      ?inv a wm:Investor .
      ?inv wm:category ?cat .
    } GROUP BY ?cat
  }
} ORDER BY ?cat

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?underfundedGoalCount WHERE {
  {
    SELECT ?investor (COUNT(?goal) AS ?underfundedGoalCount) WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:shortfall ?shortfall .
      FILTER (xsd:decimal(?shortfall) > 0)
    }
    GROUP BY ?investor
    HAVING (COUNT(?goal) >= 3)
  }
  ?investor a wm:Investor .
  OPTIONAL { ?investor wm:investorId ?investorId . }
  OPTIONAL { ?investor wm:investorName ?investorName . }
}
ORDER BY ?investorId

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon
       (AVG(?riskScore) AS ?avgRiskScore)
       (AVG(?liquidityScore) AS ?avgLiquidityScore)
       (AVG(?diversificationScore) AS ?avgDiversificationScore)
WHERE {
  ?ph a wm:PortfolioHealth ;
      wm:riskScore ?riskScore ;
      wm:liquidityScore ?liquidityScore ;
      wm:diversificationScore ?diversificationScore ;
      wm:healthOfInvestor/wm:hasTimeHorizon ?timeHorizon .
}
GROUP BY ?timeHorizon
ORDER BY ?timeHorizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorName ?investorId
WHERE {
  ?inv a wm:Investor ;
       wm:segment ?seg ;
       wm:investorName ?investorName ;
       wm:investorId ?investorId .
  FILTER(LCASE(STR(?seg)) = "conservative")
  FILTER EXISTS {
    ?holding a wm:PortfolioHolding ;
             wm:heldByInvestor ?inv ;
             wm:hasInvestmentType ?invType .
    ?invType rdfs:label ?typeLabel .
    FILTER(LCASE(STR(?typeLabel)) = "equity")
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .
  FILTER EXISTS {
    ?inv wm:hasTimeHorizon ?th .
    ?th rdfs:label ?thLabel .
    FILTER(CONTAINS(LCASE(STR(?thLabel)), "long-term"))
  }
  FILTER EXISTS {
    ?inv wm:hasInvestmentGoal ?goal .
    ?goal wm:hasInvestmentGoalType ?gt .
    ?gt rdfs:label ?gtLabel .
    FILTER(CONTAINS(LCASE(STR(?gtLabel)), "retirement planning"))
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTol ?riskTolLabel ?goalType ?goalTypeLabel (COUNT(?goal) AS ?goalCount)
WHERE {
  OPTIONAL {
    ?riskTol a wm:RiskTolerance .
    OPTIONAL { ?riskTol rdfs:label ?riskTolLabel . }
  }
  ?goal a wm:InvestmentGoal ;
        wm:hasInvestmentGoalType ?goalType .
  OPTIONAL { ?goalType rdfs:label ?goalTypeLabel . }
}
GROUP BY ?riskTol ?riskTolLabel ?goalType ?goalTypeLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:riskTolerance ?rtLiteral ;
       wm:hasRebalancingAction ?ra .
  OPTIONAL { ?inv wm:investorName ?investorName . }
  FILTER(LCASE(STR(?rtLiteral)) = "aggressive")
  ?ra wm:logic ?logic .
  FILTER(CONTAINS(LCASE(STR(?logic)), "momentum"))
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment (AVG(?goalAvgProgress) AS ?avgProgressPct)
WHERE {
  {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?goalAvgProgress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:progressPct ?progressPct ;
            wm:belongsToInvestor ?investor .
    }
    GROUP BY ?investor
  }
  ?investor a wm:Investor ;
            wm:segment ?segment .
}
GROUP BY ?segment
ORDER BY DESC(?avgProgressPct)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance (AVG(xsd:decimal(?progressPct)) AS ?avgProgressPct) (AVG(xsd:decimal(?shortfall)) AS ?avgShortfall)
WHERE {
  ?inv a wm:Investor ;
       wm:riskTolerance ?riskTolerance .
  ?goal a wm:InvestmentGoal ;
        wm:belongsToInvestor ?inv ;
        wm:progressPct ?progressPct ;
        wm:shortfall ?shortfall .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance (SUM(xsd:decimal(?amount)) AS ?totalAmount) (AVG(xsd:decimal(?gap)) AS ?avgGap) ?riskLabel
WHERE {
  ?ra a wm:RebalancingAction ;
      wm:amount ?amount ;
      wm:targetAllocationPct ?targetPct ;
      wm:currentAllocationPct ?currentPct ;
      wm:rebalancingActionOfInvestor ?inv .
  BIND(xsd:decimal(?targetPct) - xsd:decimal(?currentPct) AS ?gap) .
  ?inv wm:hasRiskTolerance ?riskTolerance .
  OPTIONAL { ?riskTolerance rdfs:label ?riskLabel . }
}
GROUP BY ?riskTolerance ?riskLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizonLabel ?avgChangePct ?avgSectorAllocationPct WHERE {
  {
    SELECT ?th (AVG(?change) AS ?avgChangePct) WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:newAllocationPct ?new ;
          wm:currentAllocationPct ?cur ;
          wm:scenarioRebalancingOfInvestor ?inv .
      ?inv wm:hasTimeHorizon ?th .
      BIND (xsd:decimal(?new) - xsd:decimal(?cur) AS ?change)
    } GROUP BY ?th
  }
  {
    SELECT ?th (AVG(?alloc) AS ?avgSectorAllocationPct) WHERE {
      ?sa a wm:SectorAllocation ;
          wm:allocationPct ?allocRaw ;
          wm:allocationOfInvestor ?inv .
      ?inv wm:hasTimeHorizon ?th .
      BIND (xsd:decimal(?allocRaw) AS ?alloc)
    } GROUP BY ?th
  }
  ?th rdfs:label ?timeHorizonLabel .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investmentGoal
       (SUM(?totalCashFlow) AS ?totalCashFlow)
       (AVG(?totalCashFlow) AS ?avgCashFlow)
       (COUNT(DISTINCT ?investor) AS ?numInvestors)
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?totalCashFlow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?investor ;
          wm:amount ?amount .
    }
    GROUP BY ?investor
  }
  ?investor wm:hasInvestmentGoal ?ig .
  ?ig wm:investmentGoal ?investmentGoal .
}
GROUP BY ?investmentGoal
ORDER BY DESC(?totalCashFlow)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investmentTypeLabel 
       (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore) 
       (AVG(xsd:decimal(?liquidityScore)) AS ?avgLiquidityScore) 
       (AVG(xsd:decimal(?diversificationScore)) AS ?avgDiversificationScore) 
       (AVG(xsd:decimal(?goalMatchPct)) AS ?avgGoalMatchPct)
WHERE {
  {
    SELECT DISTINCT ?investmentTypeLabel ?riskScore ?liquidityScore ?diversificationScore ?goalMatchPct WHERE {
      ?inv a wm:Investor ;
           wm:hasPortfolioHealth ?health ;
           wm:hasHolding ?holding .
      ?holding wm:hasInvestmentType ?invType .
      ?invType rdfs:label ?investmentTypeLabel .
      ?health wm:riskScore ?riskScore ;
              wm:liquidityScore ?liquidityScore ;
              wm:diversificationScore ?diversificationScore ;
              wm:goalMatchPct ?goalMatchPct .
    }
  }
}
GROUP BY ?investmentTypeLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cashFlowType (SUM(xsd:decimal(?raAmount)) AS ?totalRebalancingAmount)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?raAmt)) AS ?raAmount)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:investorId ?investorId ;
          wm:amount ?raAmt .
    }
    GROUP BY ?investorId
  }
  {
    SELECT DISTINCT ?investorId ?cashFlowType
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:hasCashFlowType ?cashFlowType .
    }
  }
}
GROUP BY ?cashFlowType

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?scenario (AVG(xsd:decimal(?shortfall)) AS ?avgShortfall)
WHERE {
  ?reb a wm:ScenarioRebalancing ;
       wm:scenario ?scenario ;
       wm:scenarioRebalancingOfInvestor ?investor .
  ?goal a wm:InvestmentGoal ;
        wm:belongsToInvestor ?investor ;
        wm:shortfall ?shortfall .
}
GROUP BY ?scenario
ORDER BY DESC(?avgShortfall)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?logic ?scenario (AVG(?delta) AS ?avgDeltaAllocation)
WHERE {
  # Aggregate scenario change per investor
  {
    SELECT ?investorId ?scenario ( (AVG(xsd:decimal(?newAlloc)) - AVG(xsd:decimal(?currAlloc))) AS ?delta )
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?investorId ;
          wm:scenario ?scenario ;
          wm:newAllocationPct ?newAlloc ;
          wm:currentAllocationPct ?currAlloc .
    }
    GROUP BY ?investorId ?scenario
  }
  # Get a single representative logic per investor
  {
    SELECT ?investorId (SAMPLE(?logic) AS ?logic)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:investorId ?investorId ;
          wm:logic ?logic .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?logic ?scenario

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sector ?totalAllocationPct ?avgHoldingReturnPct
WHERE {
  {
    SELECT ?sector (SUM(xsd:decimal(?allocPct)) AS ?totalAllocationPct)
    WHERE {
      ?alloc a wm:SectorAllocation ;
            wm:sector ?sector ;
            wm:allocationPct ?allocPct .
    }
    GROUP BY ?sector
  }
  {
    SELECT ?sector (AVG(xsd:decimal(?retPct)) AS ?avgHoldingReturnPct)
    WHERE {
      ?hold a wm:PortfolioHolding ;
            wm:sector ?sector ;
            wm:returnsPct ?retPct .
    }
    GROUP BY ?sector
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sourceTable ?totalCashFlow ?avgAllocChange
WHERE {
  {
    SELECT ?sourceTable (SUM(xsd:decimal(?amount)) AS ?totalCashFlow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:sourceTable ?sourceTable ;
          wm:amount ?amount .
    }
    GROUP BY ?sourceTable
  }
  {
    SELECT ?sourceTable (AVG(xsd:decimal(?newPct) - xsd:decimal(?currPct)) AS ?avgAllocChange)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:sourceTable ?sourceTable ;
          wm:newAllocationPct ?newPct ;
          wm:currentAllocationPct ?currPct .
    }
    GROUP BY ?sourceTable
  }
}
ORDER BY DESC(?totalCashFlow)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investor ?category ?label
WHERE {
  ?investor a wm:Investor .
  OPTIONAL { ?investor wm:category ?catLiteral . }
  OPTIONAL {
    ?investor wm:hasCategory ?catNode .
    ?catNode rdfs:label ?catLabel .
  }
  BIND( COALESCE(?catLabel, ?catLiteral) AS ?category )
  FILTER( LCASE(?category) NOT IN ("equity", "hybrid", "gold", "real estate", "debt") )
  OPTIONAL { ?investor rdfs:label ?label }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  ?investor a wm:Investor ;
            wm:hasSegment ?segment .
  {
    SELECT ?investor (GROUP_CONCAT(DISTINCT ?hSeg; separator="|") AS ?heldSegs)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:hasSegment ?hSeg .
    }
    GROUP BY ?investor
  }
  FILTER(CONTAINS(CONCAT("|", ?heldSegs, "|"), CONCAT("|", ?segment, "|")))
}
GROUP BY ?segment

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor .
  OPTIONAL { ?inv kg:investorId ?investorId . }
  OPTIONAL { ?inv kg:investorName ?investorName . }

  FILTER NOT EXISTS { ?inv wm:investmentGoal ?_ . }
  FILTER NOT EXISTS { ?inv wm:riskTolerance ?_ . }
  FILTER NOT EXISTS { ?inv wm:timeHorizon ?_ . }
  FILTER NOT EXISTS { ?inv wm:sectorFocus ?_ . }
  FILTER NOT EXISTS { ?inv wm:segment ?_ . }
  FILTER NOT EXISTS { ?inv wm:category ?_ . }
}

