SELECT ?holding ?holdingId ?investmentName WHERE {
  ?holding a wm:PortfolioHolding .
  OPTIONAL { ?holding wm:holdingId ?holdingId . }
  OPTIONAL { ?holding wm:investmentName ?investmentName . }

  FILTER NOT EXISTS { ?holding wm:investmentType ?_ . }
  FILTER NOT EXISTS { ?holding wm:hasInvestmentType ?_ . }
  FILTER NOT EXISTS { ?holding wm:sector ?_ . }
  FILTER NOT EXISTS { ?holding wm:hasSector ?_ . }
  FILTER NOT EXISTS { ?holding wm:segment ?_ . }
  FILTER NOT EXISTS { ?holding wm:hasSegment ?_ . }
  FILTER NOT EXISTS { ?holding wm:category ?_ . }
  FILTER NOT EXISTS { ?holding wm:hasCategory ?_ . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
