PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:investorId ?investorId . }
  OPTIONAL { ?inv wm:investorName ?investorName . }
  FILTER NOT EXISTS { ?inv wm:category ?invCat . }
  ?inv wm:hasHolding ?hold .
  ?hold wm:category ?holdCat .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category (SUM(?invCount) AS ?profileCount) (SUM(?holdCount) AS ?holdingCount)
WHERE {
  {
    SELECT ?category (COUNT(DISTINCT ?inv) AS ?invCount) (0 AS ?holdCount)
    WHERE {
      ?inv a wm:Investor .
      ?inv wm:category ?category .
    }
    GROUP BY ?category
  }
  UNION
  {
    SELECT ?category (0 AS ?invCount) (COUNT(DISTINCT ?hold) AS ?holdCount)
    WHERE {
      ?hold a wm:PortfolioHolding .
      ?hold wm:category ?category .
    }
    GROUP BY ?category
  }
}
GROUP BY ?category
ORDER BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment (COALESCE(?invCount, 0) AS ?investorCount) (COALESCE(?holdCount, 0) AS ?holdingCount)
WHERE {
  {
    SELECT DISTINCT ?segment WHERE {
      { ?inv a wm:Investor ; wm:segment ?segment . }
      UNION
      { ?hold a wm:PortfolioHolding ; wm:segment ?segment . }
    }
  }
  OPTIONAL {
    SELECT ?segment (COUNT(DISTINCT ?inv) AS ?invCount) WHERE {
      ?inv a wm:Investor ; wm:segment ?segment .
    } GROUP BY ?segment
  }
  OPTIONAL {
    SELECT ?segment (COUNT(DISTINCT ?hold) AS ?holdCount) WHERE {
      ?hold a wm:PortfolioHolding ; wm:segment ?segment .
    } GROUP BY ?segment
  }
}

