PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?holdingId ?investmentName WHERE {
  ?holding a wm:PortfolioHolding .
  OPTIONAL { ?holding wm:holdingId ?holdingId . }
  OPTIONAL { ?holding wm:investmentName ?investmentName . }
  MINUS {
    ?holding wm:heldByInvestor ?inv .
    ?inv a wm:Investor .
  }
  MINUS {
    ?holding wm:investorId ?invId .
    ?inv2 a wm:Investor ;
          wm:investorId ?invId .
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName ?totalCurrentValue WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?cv)) AS ?totalCurrentValue) WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?cv .
    }
    GROUP BY ?investor
    HAVING (SUM(xsd:decimal(?cv)) > 10000000)
  }
  ?investor a wm:Investor ;
            wm:investorName ?investorName .
}
ORDER BY DESC(?totalCurrentValue)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance (SUM(?totalCost) AS ?totalHoldingCost) (SUM(?totalCurrent) AS ?totalCurrentValue)
WHERE {
  {
    SELECT ?inv (SUM(xsd:decimal(?cost)) AS ?totalCost) (SUM(xsd:decimal(?currentValue)) AS ?totalCurrent)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?inv ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue .
    }
    GROUP BY ?inv
  }
  ?inv a wm:Investor ;
       wm:riskTolerance ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName ?totalGain WHERE {
  {
    SELECT ?inv (SUM(?gain) AS ?totalGain) WHERE {
      ?inv a wm:Investor ;
           wm:hasHolding ?holding .
      ?holding wm:currentValue ?cv ;
               wm:cost ?c .
      BIND(xsd:decimal(?cv) - xsd:decimal(?c) AS ?gain)
    }
    GROUP BY ?inv
    ORDER BY DESC(?totalGain)
    LIMIT 10
  }
  ?inv wm:investorName ?investorName .
}
ORDER BY DESC(?totalGain)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?bucket (SUM(?invCashFlow) AS ?netCashFlow)
WHERE {
  {
    SELECT ?inv (SUM(xsd:decimal(?amount)) AS ?invCashFlow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:amount ?amount .
    }
    GROUP BY ?inv
  }
  {
    SELECT ?inv (IF(MIN(?months) <= 12, "Short",
                   IF(MIN(?months) <= 60, "Medium", "Long")) AS ?bucket)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv ;
            wm:timeToGoalMonths ?months .
    }
    GROUP BY ?inv
  }
}
GROUP BY ?bucket
ORDER BY ?bucket

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?logic (SUM(?cashFlowSum) AS ?netCashFlow)
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?amt)) AS ?cashFlowSum)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?investor ;
          wm:amount ?amt .
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor ?logic
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:rebalancingActionOfInvestor ?investor ;
          wm:hasRebalancingLogic ?logic .
    }
    GROUP BY ?investor ?logic
  }
}
GROUP BY ?logic

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
