PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?scenario (SUM(?investorCash) AS ?netCashFlow) WHERE {
  {
    SELECT DISTINCT ?scenario ?investor WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:scenario ?scenario ;
          wm:scenarioRebalancingOfInvestor ?investor .
    }
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?investorCash) WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?investor ;
          wm:amount ?amount .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?scenario

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:investorId ?investorId . }
  OPTIONAL { ?inv wm:investorName ?investorName . }

  FILTER EXISTS {
    ?inv wm:hasScenarioRebalancing ?sr .
    ?sr wm:hasMarketScenario ?ms .
    OPTIONAL { ?ms rdfs:label ?msLabel . }
    FILTER (CONTAINS(LCASE(STR(?msLabel)), "bear market"))
  }

  FILTER EXISTS {
    ?inv wm:hasCashFlow ?cf .
    OPTIONAL { ?cf wm:type ?cfType . }
    FILTER (CONTAINS(LCASE(STR(?cfType)), "withdrawal"))
  }
}

