SELECT DISTINCT ?investorId ?investorName WHERE {
  ?cashFlow a wm:CashFlow ;
            wm:date ?date ;
            wm:cashFlowOfInvestor ?investor .
  FILTER ( xsd:date(?date) > "2026-04-28"^^xsd:date )
  OPTIONAL { ?investor wm:investorId ?investorId . }
  OPTIONAL { ?investor wm:investorName ?investorName . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?totalShortfall WHERE {
  {
    SELECT ?inv (SUM(xsd:decimal(?shortfall)) AS ?totalShortfall) WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv ;
            wm:shortfall ?shortfall .
      FILTER(BOUND(?shortfall))
    }
    GROUP BY ?inv
  }
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }
}
ORDER BY DESC(?totalShortfall)
LIMIT 5

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolLabel ?riskBand (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  ?investor a wm:Investor .
  ?investor wm:hasHolding ?holding .   # ensure the investor holds at least one investment

  OPTIONAL {
    ?investor wm:hasRiskTolerance ?riskTol .
    OPTIONAL { ?riskTol rdfs:label ?riskTolLabel . }
  }

  OPTIONAL {
    ?investor wm:hasPortfolioHealth ?ph .
    ?ph wm:riskScore ?riskScore .
    BIND (STR(?riskScore) AS ?riskBand)
  }
}
GROUP BY ?riskTolLabel ?riskBand

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  # Investor has at least one Withdrawal cash flow
  FILTER EXISTS {
    ?inv wm:hasCashFlow ?cf .
    ?cf wm:hasCashFlowType ?cft .
    OPTIONAL { ?cft rdfs:label ?cftLabel . }
    OPTIONAL { ?cf wm:type ?cfType . }
    FILTER (
      (BOUND(?cftLabel) && CONTAINS(LCASE(STR(?cftLabel)), "withdrawal")) ||
      (BOUND(?cfType) && CONTAINS(LCASE(STR(?cfType)), "withdrawal"))
    )
  }

  # Investor has at least one Bear Market scenario
  FILTER EXISTS {
    ?inv wm:hasScenarioRebalancing ?sr .
    ?sr wm:hasMarketScenario ?ms .
    OPTIONAL { ?ms rdfs:label ?msLabel . }
    FILTER (BOUND(?msLabel) && CONTAINS(LCASE(STR(?msLabel)), "bear market"))
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?rtLabel ?avgGoalProgress ?avgRiskScore WHERE {
  {
    SELECT ?rt (AVG(xsd:decimal(?gp)) AS ?avgGoalProgress) WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:progressPct ?gp ;
            wm:belongsToInvestor ?invG .
      ?invG wm:hasRiskTolerance ?rt .
    } GROUP BY ?rt
  }
  {
    SELECT ?rt (AVG(xsd:decimal(?rs)) AS ?avgRiskScore) WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:riskScore ?rs ;
          wm:healthOfInvestor ?invP .
      ?invP wm:hasRiskTolerance ?rt .
    } GROUP BY ?rt
  }
  OPTIONAL { ?rt rdfs:label ?rtLabel . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTol (SUM(IF(bound(?holdingValue), xsd:decimal(?holdingValue), 0)) AS ?totalHoldingValue) (SUM(IF(bound(?allocationValue), xsd:decimal(?allocationValue), 0)) AS ?totalSectorAllocationInvestment)
WHERE {
  ?inv a wm:Investor ;
       wm:hasRiskTolerance ?riskTol .
  OPTIONAL {
    ?inv wm:hasHolding ?holding .
    ?holding wm:currentValue ?holdingValue .
  }
  OPTIONAL {
    ?inv wm:hasSectorAllocation ?alloc .
    ?alloc wm:totalInvestment ?allocationValue .
  }
}
GROUP BY ?riskTol

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?totalCurrentValue
WHERE {
  {
    SELECT ?inv ?investorId ?investorName (SUM(?currVal) AS ?totalCurrentValue)
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?investorId .
      OPTIONAL { ?inv wm:investorName ?investorName . }
      ?inv wm:hasHolding ?hold .
      ?hold wm:currentValue ?currVal .
    }
    GROUP BY ?inv ?investorId ?investorName
  }
  ?inv wm:hasPortfolioHealth ?ph .
  ?ph wm:riskScore ?riskScore .
  FILTER(?riskScore > 70)
}
ORDER BY DESC(?totalCurrentValue)
LIMIT 5

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?label ?total2025 WHERE {
  {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?avgProgress) WHERE {
      ?goal a wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:progressPct ?progressPct .
    }
    GROUP BY ?investor
    HAVING (?avgProgress < 40)
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?total2025) WHERE {
      ?cf a wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:date ?date .
      FILTER(CONTAINS(LCASE(STR(?date)), "2025"))
      ?cf wm:amount ?amount .
    }
    GROUP BY ?investor
  }
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor rdfs:label ?label . }
}
ORDER BY DESC(?total2025)
LIMIT 5

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  FILTER EXISTS {
    ?holding wm:heldByInvestor ?inv ;
             wm:purchaseDate ?pdate .
    FILTER(CONTAINS(LCASE(STR(?pdate)), "2025"))
  }

  FILTER EXISTS {
    ?cf wm:cashFlowOfInvestor ?inv ;
        wm:date ?cdate .
    FILTER(CONTAINS(LCASE(STR(?cdate)), "2025"))
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance (COALESCE(?totalPurchases, 0) AS ?totalPurchases) (COALESCE(?totalCashFlow, 0) AS ?totalCashFlow) WHERE {
  {
    SELECT DISTINCT ?riskTolerance WHERE {
      { ?h a wm:PortfolioHolding ;
           wm:purchaseDate ?pd ;
           wm:heldByInvestor ?inv .
        FILTER regex(?pd, "^2024")
        ?inv wm:riskTolerance ?riskTolerance .
      } UNION {
        ?cf a wm:CashFlow ;
            wm:date ?d ;
            wm:cashFlowOfInvestor ?inv .
        FILTER regex(?d, "^2024")
        ?inv wm:riskTolerance ?riskTolerance .
      }
    }
  }
  OPTIONAL {
    SELECT ?riskTolerance (SUM(xsd:decimal(?cost)) AS ?totalPurchases) WHERE {
      ?h a wm:PortfolioHolding ;
         wm:cost ?cost ;
         wm:purchaseDate ?pd ;
         wm:heldByInvestor ?inv .
      FILTER regex(?pd, "^2024")
      ?inv wm:riskTolerance ?riskTolerance .
    }
    GROUP BY ?riskTolerance
  }
  OPTIONAL {
    SELECT ?riskTolerance (SUM(xsd:decimal(?amount)) AS ?totalCashFlow) WHERE {
      ?cf a wm:CashFlow ;
         wm:amount ?amount ;
         wm:date ?d ;
         wm:cashFlowOfInvestor ?inv .
      FILTER regex(?d, "^2024")
      ?inv wm:riskTolerance ?riskTolerance .
    }
    GROUP BY ?riskTolerance
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?avgProgress ?riskScore ?liquidityScore
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avgProgress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
    HAVING (AVG(xsd:decimal(?progressPct)) < 20)
  }
  ?ph a wm:PortfolioHealth ;
      wm:investorId ?investorId ;
      wm:riskScore ?riskScore ;
      wm:liquidityScore ?liquidityScore .
  FILTER (xsd:decimal(?riskScore) < 30 && xsd:decimal(?liquidityScore) < 30)
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .
}
ORDER BY ?investorName

