PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:hasSectorAllocation ?alloc ;
       wm:hasPortfolioHealth ?ph .
  OPTIONAL { ?inv wm:investorName ?investorName . }
  ?alloc wm:allocationPct ?allocPct .
  FILTER(xsd:decimal(?allocPct) > 50) .
  ?ph wm:diversificationScore ?divScore .
  FILTER(xsd:decimal(?divScore) < 25) .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?totalShortfall ?totalHoldingGain ?netCashFlow
WHERE {
  {
    SELECT ?inv (SUM(?shortfall) AS ?totalShortfall) (SUM(?gain) AS ?totalHoldingGain) (SUM(?amount) AS ?netCashFlow)
    WHERE {
      ?inv a wm:Investor .
      OPTIONAL {
        ?goal a wm:InvestmentGoal ;
              wm:shortfall ?shortfall ;
              wm:belongsToInvestor ?inv .
      }
      OPTIONAL {
        ?holding a wm:PortfolioHolding ;
                 wm:heldByInvestor ?inv ;
                 wm:cost ?cost ;
                 wm:currentValue ?curr .
        BIND ((?curr - ?cost) AS ?gain)
      }
      OPTIONAL {
        ?cf a wm:CashFlow ;
            wm:cashFlowOfInvestor ?inv ;
            wm:amount ?amount .
      }
    }
    GROUP BY ?inv
    HAVING (SUM(?shortfall) > 0 && SUM(?gain) < 0 && SUM(?amount) < 10000)
  }
  OPTIONAL { ?inv wm:investorId ?investorId . }
  OPTIONAL { ?inv wm:investorName ?investorName . }
}
ORDER BY ?investorId

