SELECT ?segmentLabel ?riskBand (COUNT(DISTINCT ?inv) AS ?investorCount)
WHERE {
  ?inv a wm:Investor ;
       wm:hasSegment ?seg ;
       wm:hasPortfolioHealth ?ph .
  ?seg rdfs:label ?segmentLabel .
  ?ph wm:diversificationScore ?divScore ;
      wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?divScore) < 30)

  BIND(
    IF (xsd:decimal(?riskScore) < 33, "Low",
        IF (xsd:decimal(?riskScore) < 66, "Medium", "High")
    ) AS ?riskBand
  )
}
GROUP BY ?segmentLabel ?riskBand

