PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sectorLabel ?avgReturnsPct ?avgDiversificationScore WHERE {
  {
    SELECT ?sector ?sectorLabel (AVG(?returnsPct) AS ?avgReturnsPct)
    WHERE {
      ?holding wm:hasSector ?sector ;
               wm:returnsPct ?returnsPct .
      ?sector rdfs:label ?sectorLabel .
    }
    GROUP BY ?sector ?sectorLabel
  }
  {
    SELECT ?sector ?sectorLabel (AVG(?divScore) AS ?avgDiversificationScore)
    WHERE {
      {
        SELECT DISTINCT ?sector ?investorId
        WHERE {
          ?holding wm:hasSector ?sector ;
                   wm:investorId ?investorId .
        }
      }
      ?health wm:investorId ?investorId ;
              wm:diversificationScore ?divScore .
      ?sector rdfs:label ?sectorLabel .
    }
    GROUP BY ?sector ?sectorLabel
  }
}

