PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sector (AVG(xsd:decimal(?allocPct)) AS ?avgAllocationPct)
WHERE {
  {
    SELECT DISTINCT ?inv
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:riskScore ?riskScore ;
          wm:healthOfInvestor ?inv .
      FILTER(xsd:decimal(?riskScore) > 70)
    }
  }
  ?sa a wm:SectorAllocation ;
      wm:allocationOfInvestor ?inv ;
      wm:sector ?sector ;
      wm:allocationPct ?allocPct .
}
GROUP BY ?sector
ORDER BY DESC(?avgAllocationPct)
LIMIT 5

