    }
    GROUP BY ?invId
    HAVING (AVG(xsd:decimal(?prog)) < 30)
  }
  FILTER(?investorId = ?invId)

  {
    SELECT ?invId2 ?riskScore WHERE {
      ?ph a wm:PortfolioHealth ;
           wm:investorId ?invId2 ;
           wm:riskScore ?riskScore .
      FILTER(xsd:decimal(?riskScore) > 60)
    }
