PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  FILTER EXISTS {
    ?inv wm:hasCashFlow ?cf .
    ?cf wm:hasCashFlowType ?cft .
    ?cft rdfs:label ?cftLabel .
    FILTER(CONTAINS(LCASE(STR(?cftLabel)), "withdrawal"))
  }

  FILTER EXISTS {
    ?inv wm:hasRebalancingAction ?ra .
    ?ra wm:action ?raAction .
    FILTER(CONTAINS(LCASE(STR(?raAction)), "de-risking"))
  }
