PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskGroup ?avgShortfall ?avgRiskScore WHERE {
  {
    SELECT ?riskGroup (AVG(xsd:decimal(?sf)) AS ?avgShortfall) WHERE {
      ?inv a wm:Investor ;
           wm:riskTolerance ?riskGroup .
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv ;
            wm:shortfall ?sf .
    } GROUP BY ?riskGroup
  }
  OPTIONAL {
    SELECT ?riskGroup (AVG(xsd:decimal(?rs)) AS ?avgRiskScore) WHERE {
      ?inv a wm:Investor ;
           wm:riskTolerance ?riskGroup .
      ?ph a wm:PortfolioHealth ;
          wm:healthOfInvestor ?inv ;
          wm:riskScore ?rs .
    } GROUP BY ?riskGroup
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sectorLabel ?totalHoldingValue ?totalSectorAllocation WHERE {
  ?sec a wm:Sector .
  ?sec rdfs:label ?sectorLabel .

  OPTIONAL {
    SELECT ?sec (SUM(xsd:decimal(?cv)) AS ?totalHoldingValue) WHERE {
      ?holding wm:hasSector ?sec .
      ?holding wm:currentValue ?cv .
    }
    GROUP BY ?sec
  }

  OPTIONAL {
    SELECT ?sec (SUM(xsd:decimal(?ti)) AS ?totalSectorAllocation) WHERE {
      ?alloc wm:hasSector ?sec .
      ?alloc wm:totalInvestment ?ti .
    }
    GROUP BY ?sec
  }
}
ORDER BY ?sectorLabel

