PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  FILTER EXISTS { ?inv wm:hasPortfolioHealth ?ph . }
  FILTER EXISTS { ?inv wm:hasHolding ?hold . }
  FILTER NOT EXISTS { ?inv wm:hasRiskTolerance ?rt . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?rtName ?rlName (COUNT(DISTINCT ?inv) AS ?investorCount)
WHERE {
  ?inv a wm:Investor .
  ?inv wm:hasRiskTolerance ?rt .
  OPTIONAL { ?rt rdfs:label ?rtLabel . }
  BIND(COALESCE(?rtLabel, STR(?rt)) AS ?rtName)

  FILTER EXISTS {
    ?inv wm:hasScenarioRebalancing ?sr .
    ?sr a wm:ScenarioRebalancing .
  }

  OPTIONAL {
    ?inv wm:hasRebalancingAction ?ra .
    ?ra wm:hasRebalancingLogic ?rl .
    OPTIONAL { ?rl rdfs:label ?rlLabel . }
    BIND(COALESCE(?rlLabel, STR(?rl)) AS ?rlTmp)
  }
  BIND(COALESCE(?rlTmp, "None") AS ?rlName)
}
GROUP BY ?rtName ?rlName

