  {
    SELECT DISTINCT ?investor ?sector WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:hasSector ?sector .
    }
  }
  ?sector rdfs:label ?sectorLabel .
}
GROUP BY ?sectorLabel
ORDER BY DESC(?avgDiversificationScore)

