PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance 
       (AVG(?avgProgress) AS ?avgGoalProgress) 
       (AVG(xsd:decimal(?riskScore)) AS ?avgHealthRisk) 
       (AVG(xsd:decimal(?liquidityScore)) AS ?avgLiquidity)
WHERE {
  ?inv a wm:Investor ;
       wm:riskTolerance ?riskTolerance ;
       wm:hasPortfolioHealth ?ph .
  ?ph wm:riskScore ?riskScore ;
      wm:liquidityScore ?liquidityScore .

  OPTIONAL {
    {
      SELECT ?inv (AVG(xsd:decimal(?progressPct)) AS ?avgProgress)
      WHERE {
        ?inv wm:hasInvestmentGoal ?goal .
        ?goal wm:progressPct ?progressPct .
      }
      GROUP BY ?inv
    }
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(?invHoldingReturn) AS ?avgHoldingReturn)
       (AVG(?invRiskScore) AS ?avgHealthRisk)
       (AVG(?invDivScore) AS ?avgDiversification)
WHERE {
  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:riskTolerance ?riskTolerance . }

  {
    SELECT ?inv (AVG(xsd:decimal(?returnsPct)) AS ?invHoldingReturn)
    WHERE {
      ?inv wm:hasHolding ?h .
      ?h wm:returnsPct ?returnsPct .
    }
    GROUP BY ?inv
  }

  {
    SELECT ?inv (AVG(xsd:decimal(?riskScore)) AS ?invRiskScore)
           (AVG(xsd:decimal(?divScore)) AS ?invDivScore)
    WHERE {
      ?inv wm:hasPortfolioHealth ?ph .
      ?ph wm:riskScore ?riskScore .
      ?ph wm:diversificationScore ?divScore .
    }
    GROUP BY ?inv
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTol ?totalCashFlow ?avgProgressPct ?totalShortfall WHERE {
  {
    SELECT ?riskTol (SUM(?amount) AS ?totalCashFlow) WHERE {
      ?inv a wm:Investor .
      ?inv wm:riskTolerance ?riskTol .
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:amount ?amount .
    } GROUP BY ?riskTol
  }
  OPTIONAL {
    SELECT ?riskTol (AVG(?progress) AS ?avgProgressPct) (SUM(?shortfall) AS ?totalShortfall) WHERE {
      ?inv a wm:Investor .
      ?inv wm:riskTolerance ?riskTol .
      ?inv wm:hasInvestmentGoal ?goal .
      ?goal wm:progressPct ?progress .
      ?goal wm:shortfall ?shortfall .
    } GROUP BY ?riskTol
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskLabel (AVG(?avgAllocPct) AS ?avgAllocationPct) (AVG(?avgRetPct) AS ?avgReturnPct) (SUM(?totalVal) AS ?totalHoldingValue)
WHERE {
  {
    SELECT ?investor (AVG(?allocPct) AS ?avgAllocPct)
    WHERE {
      ?alloc wm:allocationOfInvestor ?investor ;
            wm:allocationPct ?allocPct .
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(?retPct) AS ?avgRetPct) (SUM(?currVal) AS ?totalVal)
    WHERE {
      ?hold wm:heldByInvestor ?investor ;
            wm:returnsPct ?retPct ;
            wm:currentValue ?currVal .
    }
    GROUP BY ?investor
  }
  ?investor wm:hasRiskTolerance ?risk .
  ?risk rdfs:label ?riskLabel .
}
GROUP BY ?riskLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?totalRebalanceAmount ?rebalanceCount ?totalCashFlowAmount ?cashFlowCount
WHERE {
  {
    SELECT ?riskTolerance (SUM(xsd:decimal(?raAmount)) AS ?totalRebalanceAmount) (COUNT(?ra) AS ?rebalanceCount)
    WHERE {
      ?inv a wm:Investor ;
           wm:riskTolerance ?riskTolerance .
      ?ra a wm:RebalancingAction ;
          wm:rebalancingActionOfInvestor ?inv ;
          wm:amount ?raAmount .
    }
    GROUP BY ?riskTolerance
  }
  OPTIONAL {
    SELECT ?riskTolerance (SUM(xsd:decimal(?cfAmount)) AS ?totalCashFlowAmount) (COUNT(?cf) AS ?cashFlowCount)
    WHERE {
      ?inv a wm:Investor ;
           wm:riskTolerance ?riskTolerance .
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:amount ?cfAmount .
    }
    GROUP BY ?riskTolerance
  }
}
ORDER BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTol ?totalScenarios ?avgProgressPct ?avgVolatilityPct WHERE {
  {
    SELECT ?riskTol (SUM(?cnt) AS ?totalScenarios) WHERE {
      {
        SELECT ?investorId (COUNT(?sr) AS ?cnt) WHERE {
          ?sr a wm:ScenarioRebalancing .
          ?sr wm:scenarioRebalancingOfInvestor ?inv .
          ?inv wm:investorId ?investorId .
        } GROUP BY ?investorId
      }
      ?inv wm:investorId ?investorId .
      ?inv wm:riskTolerance ?riskTol .
    } GROUP BY ?riskTol
  }
  {
    SELECT ?riskTol (AVG(xsd:decimal(?progress)) AS ?avgProgressPct) (AVG(xsd:decimal(?vol)) AS ?avgVolatilityPct) WHERE {
      ?goal a wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?inv .
      ?inv wm:riskTolerance ?riskTol .
      OPTIONAL { ?goal wm:progressPct ?progress . }
      OPTIONAL { ?goal wm:avgVolatilityPct ?vol . }
    } GROUP BY ?riskTol
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(?scenarioChange) AS ?avgScenarioChange)
       (AVG(?rebalanceGap) AS ?avgRebalanceGap)
       (AVG(?amount) AS ?avgAmount)
WHERE {
  {
    SELECT ?inv (AVG(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?scenarioChange)
    WHERE {
      ?inv a wm:Investor ;
           wm:hasScenarioRebalancing ?sr .
      ?sr wm:newAllocationPct ?newAlloc ;
          wm:currentAllocationPct ?currAlloc .
    }
    GROUP BY ?inv
  }
  {
    SELECT ?inv (AVG(xsd:decimal(?targetAlloc) - xsd:decimal(?currAllocAct)) AS ?rebalanceGap)
           (AVG(xsd:decimal(?amt)) AS ?amount)
    WHERE {
      ?inv a wm:Investor ;
           wm:hasRebalancingAction ?ra .
      ?ra wm:targetAllocationPct ?targetAlloc ;
          wm:currentAllocationPct ?currAllocAct ;
          wm:amount ?amt .
    }
    GROUP BY ?inv
  }
  ?inv wm:riskTolerance ?riskTolerance .
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?totalCashFlow ?avgAllocChange ?scenarioCount WHERE {
  {
    SELECT ?riskTolerance (SUM(xsd:decimal(?amount)) AS ?totalCashFlow) WHERE {
      ?inv a wm:Investor .
      ?inv wm:riskTolerance ?riskTolerance .
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:amount ?amount .
    }
    GROUP BY ?riskTolerance
  }
  OPTIONAL {
    SELECT ?riskTolerance (AVG(xsd:decimal(?allocChange)) AS ?avgAllocChange) (COUNT(DISTINCT ?scenario) AS ?scenarioCount) WHERE {
      ?inv a wm:Investor .
      ?inv wm:riskTolerance ?riskTolerance .
      ?inv wm:hasScenarioRebalancing ?sr .
      ?sr wm:scenario ?scenario .
      ?sr wm:newAllocationPct ?new .
      ?sr wm:currentAllocationPct ?curr .
      BIND(xsd:decimal(?new) - xsd:decimal(?curr) AS ?allocChange)
    }
    GROUP BY ?riskTolerance
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon 
       (AVG(xsd:decimal(?avgProgress)) AS ?avgGoalProgress) 
       (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore) 
       (AVG(xsd:decimal(?liquidityScore)) AS ?avgLiquidityScore)
WHERE {
  ?inv a wm:Investor ;
       wm:timeHorizon ?timeHorizon .

  OPTIONAL {
    ?inv wm:hasPortfolioHealth ?ph .
    ?ph wm:riskScore ?riskScore ;
        wm:liquidityScore ?liquidityScore .
  }

  {
    SELECT ?inv (AVG(xsd:decimal(?progressPct)) AS ?avgProgress) WHERE {
      ?inv wm:hasInvestmentGoal ?goal .
      ?goal wm:progressPct ?progressPct .
    } GROUP BY ?inv
  }
}
GROUP BY ?timeHorizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon (AVG(?gain) AS ?avgHoldingGain) (AVG(?riskScore) AS ?avgRiskScore) (AVG(?divScore) AS ?avgDiversificationScore)
WHERE {
  {
    SELECT ?inv ((SUM(?curr) - SUM(?cost)) / COUNT(?holding) AS ?gain) ?riskScore ?divScore
    WHERE {
      ?inv a wm:Investor .
      OPTIONAL {
        ?inv wm:hasHolding ?holding .
        ?holding wm:currentValue ?curr .
        ?holding wm:cost ?cost .
      }
      OPTIONAL {
        ?inv wm:hasPortfolioHealth ?ph .
        ?ph wm:riskScore ?riskScore .
        ?ph wm:diversificationScore ?divScore .
      }
    }
    GROUP BY ?inv ?riskScore ?divScore
  }
  ?inv wm:timeHorizon ?timeHorizon .
}
GROUP BY ?timeHorizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon (SUM(?cfSum) AS ?totalCashFlow) (AVG(?goalProgress) AS ?avgProgressPct) (SUM(?goalShortfall) AS ?totalShortfall)
WHERE {
  ?investor wm:hasTimeHorizon ?timeHorizon .

  {
    SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?cfSum)
    WHERE {
      ?cf wm:cashFlowOfInvestor ?investor ;
          wm:amount ?amount .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?goalProgress) (SUM(xsd:decimal(?shortfall)) AS ?goalShortfall)
    WHERE {
      ?goal wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPct ;
            wm:shortfall ?shortfall .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?timeHorizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizonLabel (AVG(?allocPct) AS ?avgAllocationPct) (AVG(?returnPct) AS ?avgReturnPct) (SUM(?holdingValue) AS ?totalHoldingValue)
WHERE {
  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:hasTimeHorizon ?th . }
  OPTIONAL { ?th rdfs:label ?timeHorizonLabel . }

  {
    SELECT ?inv (AVG(?allocPctInner) AS ?allocPct)
    WHERE {
      ?alloc a wm:SectorAllocation .
      ?alloc wm:allocationOfInvestor ?inv .
      ?alloc wm:allocationPct ?allocPctInner .
    }
    GROUP BY ?inv
  }

  {
    SELECT ?inv (AVG(?returnPctInner) AS ?returnPct) (SUM(?valueInner) AS ?holdingValue)
    WHERE {
      ?hold a wm:PortfolioHolding .
      ?hold wm:heldByInvestor ?inv .
      OPTIONAL { ?hold wm:returnsPct ?returnPctInner . }
      OPTIONAL { ?hold wm:currentValue ?valueInner . }
    }
    GROUP BY ?inv
  }
}
GROUP BY ?timeHorizonLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon ?totalRebalance ?rebCount ?totalCashFlow ?cfCount WHERE {
  {
    SELECT ?timeHorizon (SUM(xsd:decimal(COALESCE(?rebAmount, 0))) AS ?totalRebalance) (COUNT(?reb) AS ?rebCount) WHERE {
      ?reb a wm:RebalancingAction .
      ?reb wm:rebalancingActionOfInvestor ?inv .
      ?inv wm:hasTimeHorizon ?timeHorizon .
      OPTIONAL { ?reb wm:amount ?rebAmount . }
    } GROUP BY ?timeHorizon
  }
  OPTIONAL {
    SELECT ?timeHorizon (SUM(xsd:decimal(COALESCE(?cfAmount, 0))) AS ?totalCashFlow) (COUNT(?cf) AS ?cfCount) WHERE {
      ?cf a wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?inv .
      ?inv wm:hasTimeHorizon ?timeHorizon .
      OPTIONAL { ?cf wm:amount ?cfAmount . }
    } GROUP BY ?timeHorizon
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon ?scenarioCount ?avgProgress ?avgVolatility WHERE {
  {
    SELECT ?timeHorizon (COUNT(DISTINCT ?scenario) AS ?scenarioCount) WHERE {
      ?inv a wm:Investor .
      ?inv wm:hasTimeHorizon ?timeHorizon .
      ?inv wm:hasScenarioRebalancing ?sr .
      ?sr wm:scenario ?scenario .
    }
    GROUP BY ?timeHorizon
  }
  {
    SELECT ?timeHorizon (AVG(xsd:decimal(?progressPct)) AS ?avgProgress) (AVG(xsd:decimal(?volatility)) AS ?avgVolatility) WHERE {
      ?inv a wm:Investor .
      ?inv wm:hasTimeHorizon ?timeHorizon .
      ?inv wm:hasInvestmentGoal ?goal .
      ?goal wm:progressPct ?progressPct .
      ?goal wm:avgVolatilityPct ?volatility .
    }
    GROUP BY ?timeHorizon
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizonLabel ?totalCashAmount ?totalScenarioRows ?distinctScenarioCount
WHERE {
  {
    SELECT ?timeHorizon (SUM(xsd:decimal(?amt)) AS ?totalCashAmount)
    WHERE {
      ?inv a wm:Investor ;
           wm:hasTimeHorizon ?timeHorizon ;
           wm:hasCashFlow ?cf .
      ?cf wm:amount ?amt .
    }
    GROUP BY ?timeHorizon
  }
  {
    SELECT ?timeHorizon (COUNT(?sr) AS ?totalScenarioRows)
    WHERE {
      ?inv a wm:Investor ;
           wm:hasTimeHorizon ?timeHorizon ;
           wm:hasScenarioRebalancing ?sr .
    }
    GROUP BY ?timeHorizon
  }
  {
    SELECT ?timeHorizon (COUNT(DISTINCT ?scenario) AS ?distinctScenarioCount)
    WHERE {
      ?inv a wm:Investor ;
           wm:hasTimeHorizon ?timeHorizon ;
           wm:hasScenarioRebalancing ?sr .
      ?sr wm:scenario ?scenario .
    }
    GROUP BY ?timeHorizon
  }
  OPTIONAL { ?timeHorizon rdfs:label ?timeHorizonLabel . }
}
ORDER BY ?timeHorizonLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (STR(?category) AS ?categoryLabel)
       (AVG(?gain) AS ?avgHoldingGain)
       (AVG(?riskScore) AS ?avgRiskScore)
       (AVG(?divScore) AS ?avgDiversificationScore)
WHERE {
  ?inv a wm:Investor ;
       wm:category ?category .

  OPTIONAL {
    ?holding a wm:PortfolioHolding ;
             wm:heldByInvestor ?inv ;
             wm:cost ?cost ;
             wm:currentValue ?curr .
    BIND(xsd:decimal(?curr) - xsd:decimal(?cost) AS ?gain)
  }

  OPTIONAL {
    ?health a wm:PortfolioHealth ;
            wm:healthOfInvestor ?inv ;
            wm:riskScore ?riskScore ;
            wm:diversificationScore ?divScore .
  }
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (SUM(?cashSum) AS ?totalCashFlow)
       (AVG(?goalAvgProgress) AS ?avgGoalProgress)
       (AVG(?goalAvgShortfall) AS ?avgGoalShortfall)
WHERE {
  ?investor a wm:Investor ;
            wm:category ?category .

  {
    SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?cashSum)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?investor ;
          wm:amount ?amount .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?goalAvgProgress)
                     (AVG(xsd:decimal(?shortfall)) AS ?goalAvgShortfall)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor .
      OPTIONAL { ?goal wm:progressPct ?progressPct . }
      OPTIONAL { ?goal wm:shortfall ?shortfall . }
    }
    GROUP BY ?investor
  }
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?categoryLabel (COALESCE(?allocSum, 0) AS ?totalAllocationPct) (COALESCE(?avgReturn, 0) AS ?avgReturnPct) (COALESCE(?holdSum, 0) AS ?totalHoldingValue)
WHERE {
  {
    SELECT ?category (SUM(xsd:decimal(?allocPct)) AS ?allocSum)
    WHERE {
      ?investor wm:hasCategory ?category .
      ?investor wm:hasSectorAllocation ?alloc .
      ?alloc wm:allocationPct ?allocPct .
    }
    GROUP BY ?category
  }
  OPTIONAL {
    SELECT ?category (AVG(xsd:decimal(?retPct)) AS ?avgReturn) (SUM(xsd:decimal(?val)) AS ?holdSum)
    WHERE {
      ?investor wm:hasCategory ?category .
      ?investor wm:hasHolding ?hold .
      ?hold wm:returnsPct ?retPct .
      ?hold wm:currentValue ?val .
    }
    GROUP BY ?category
  }
  OPTIONAL { ?category rdfs:label ?categoryLabel . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (SUM(?raSum) AS ?totalRebalancingAmount)
       (SUM(?cfSum) AS ?totalCashFlowAmount)
       (SUM(?raCount) AS ?rebalanceTransactionCount)
       (SUM(?cfCount) AS ?cashFlowTransactionCount)
WHERE {
  {
    SELECT ?category (SUM(xsd:decimal(?raAmount)) AS ?raSum) (COUNT(?ra) AS ?raCount) (0 AS ?cfSum) (0 AS ?cfCount)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:amount ?raAmount ;
          wm:rebalancingActionOfInvestor ?investor .
      ?investor a wm:Investor ;
                wm:category ?category .
    }
    GROUP BY ?category
  }
  UNION
  {
    SELECT ?category (0 AS ?raSum) (0 AS ?raCount) (SUM(xsd:decimal(?cfAmount)) AS ?cfSum) (COUNT(?cf) AS ?cfCount)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:amount ?cfAmount ;
          wm:cashFlowOfInvestor ?investor .
      ?investor a wm:Investor ;
                wm:category ?category .
    }
    GROUP BY ?category
  }
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (AVG(?scenarioCount) AS ?avgScenarioCount)
       (AVG(?goalProgress) AS ?avgGoalProgress)
       (AVG(?volatility) AS ?avgVolatility)
WHERE {
  {
    SELECT ?inv (COUNT(DISTINCT ?scenario) AS ?scenarioCount)
                 (AVG(?progressPct) AS ?goalProgress)
                 (AVG(?volPct) AS ?volatility)
    WHERE {
      ?inv a wm:Investor .
      OPTIONAL {
        ?inv wm:hasScenarioRebalancing ?sr .
        ?sr wm:scenario ?scenario .
      }
      OPTIONAL {
        ?inv wm:hasInvestmentGoal ?ig .
        ?ig wm:progressPct ?progressPct .
        ?ig wm:avgVolatilityPct ?volPct .
      }
    }
    GROUP BY ?inv
  }
  ?inv wm:hasCategory ?category .
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?categoryLabel (SUM(?scenarioCount) AS ?totalScenarios) (AVG(?gap) AS ?avgRebalancingGap) (SUM(?totalAmount) AS ?totalRebalancingAmount)
WHERE {
  ?inv a wm:Investor .
  OPTIONAL {
    ?inv wm:hasCategory ?cat .
    OPTIONAL { ?cat rdfs:label ?categoryLabel . }
  }

  {
    SELECT ?inv (COUNT(DISTINCT ?scen) AS ?scenarioCount) (AVG(?gapVal) AS ?gap)
    WHERE {
      ?inv wm:hasScenarioRebalancing ?sr .
      ?sr wm:scenario ?scen .
      ?sr wm:newAllocationPct ?newPct .
      ?sr wm:currentAllocationPct ?curPct .
      BIND (xsd:decimal(?newPct) - xsd:decimal(?curPct) AS ?gapVal)
    } GROUP BY ?inv
  }

  {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?totalAmount)
    WHERE {
      ?inv wm:hasRebalancingAction ?ra .
      ?ra wm:amount ?amt .
    } GROUP BY ?inv
  }
}
GROUP BY ?categoryLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?totalCashFlow ?scenarioChangeCount ?scenarioCount WHERE {
  {
    SELECT (SUM(xsd:decimal(?amt)) AS ?totalCashFlow) WHERE {
      ?cf wm:amount ?amt .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?scen) AS ?scenarioChangeCount) WHERE {
      ?sr wm:scenario ?scen .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?sr) AS ?scenarioCount) WHERE {
      ?sr wm:scenario ?scen .
    }
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment 
       (AVG(?avgProgressPct) AS ?segmentAvgProgressPct) 
       (AVG(?avgRiskScore) AS ?segmentAvgRiskScore) 
       (AVG(?avgLiquidityScore) AS ?segmentAvgLiquidityScore)
WHERE {
  {
    SELECT ?inv (AVG(xsd:decimal(?pg)) AS ?avgProgressPct)
    WHERE {
      ?inv a wm:Investor ;
           wm:hasInvestmentGoal ?goal .
      ?goal wm:progressPct ?pg .
    }
    GROUP BY ?inv
  }
  {
    SELECT ?inv (AVG(xsd:decimal(?risk)) AS ?avgRiskScore) (AVG(xsd:decimal(?liq)) AS ?avgLiquidityScore)
    WHERE {
      ?inv a wm:Investor ;
           wm:hasPortfolioHealth ?ph .
      ?ph wm:riskScore ?risk ;
          wm:liquidityScore ?liq .
    }
    GROUP BY ?inv
  }
  ?inv wm:segment ?segment .
}
GROUP BY ?segment

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment ?avgHoldingGain ?avgRiskScore ?avgDiversificationScore
WHERE {
  {
    SELECT ?segment (AVG(?returnsPct) AS ?avgHoldingGain)
    WHERE {
      ?holding wm:heldByInvestor ?inv .
      ?inv wm:segment ?segment .
      ?holding wm:returnsPct ?returnsPct .
    }
    GROUP BY ?segment
  }
  {
    SELECT ?segment (AVG(?riskScore) AS ?avgRiskScore) (AVG(?divScore) AS ?avgDiversificationScore)
    WHERE {
      ?ph wm:healthOfInvestor ?inv .
      ?inv wm:segment ?segment .
      ?ph wm:riskScore ?riskScore .
      ?ph wm:diversificationScore ?divScore .
    }
    GROUP BY ?segment
  }
}
ORDER BY ?segment
